    ipad=document.createElement("div"); ipad.className="ipad";
    if(ihead)ihead.after(ipad); else hero.insertBefore(ipad,hero.firstChild);
    kids=[].slice.call(hero.children);
    for(i=0;i<kids.length;i++){
      if(kids[i]!==ipad&&kids[i]!==ihead)ipad.appendChild(kids[i]);
    }
  }
  return ipad;
}

/* #count.sdcount: one element, moved never cloned. At desk width it sits in
   .ipad immediately above .rails; the insert only happens when .rails is
   really a child of the node it is being inserted into, at that moment. On
   the phone the original keeps the sentence in #p-search .bar, so it goes
   back there and the phone hero is never touched. */
function seatCount(){
  var all=document.querySelectorAll("#count"); if(!all.length)return;
  var c=all[0],i;
  for(i=0;i<all.length;i++){ if(all[i]!==c&&all[i].parentNode)all[i].parentNode.removeChild(all[i]); }
  var hero=byId("hero");
  var rails=hero?hero.querySelector(".rails"):null;
  if(rails&&rails.parentNode&&rails.parentNode.nodeType===1){
    var host=rails.parentNode;
    if(c.parentNode!==host){
      if(c.parentNode&&c.parentNode.nodeType===1&&c.parentNode.contains(c))c.parentNode.removeChild(c);
      host.insertBefore(c,rails);
    }else if(c.nextElementSibling!==rails){
      host.insertBefore(c,rails);
    }
  }else{
    var bar=document.querySelector("#p-search .bar");
    if(bar&&c.parentNode!==bar){
      if(c.parentNode&&c.parentNode.nodeType===1&&c.parentNode.contains(c))c.parentNode.removeChild(c);
      bar.insertBefore(c,bar.firstChild);
    }
  }
  if(!/\bsdcount\b/.test(c.className))c.className=("sdcount "+c.className).trim();
}

